  function decodificarTramos(texto) {
    const n = texto.split(',').map((x) => parseInt(x, 36));
    const t = new Int32Array(n.length);
    let v = 0;
    for (let i = 0; i < n.length; i++) { v += n[i]; t[i] = v; }
    return t;
  }
