  const pyError = (tipo, mensaje) => new C.PyError(tipo, mensaje);
  const nombreTipo = (v) => (Array.isArray(v) ? 'list' : esDict(v) ? 'dict' : typeof v === 'string' ? 'str' : typeof v === 'boolean' ? 'bool' : v === null || v === undefined ? 'NoneType' : 'int');
