    let antes = DIAS_ANTES_MES[month] + (month > 2 && bis ? 1 : 0);
    if (antes > n) { month -= 1; if (month < 1) return [year, 0, 0]; antes = DIAS_ANTES_MES[month] + (month > 2 && bis ? 1 : 0); }
    return [year, month, n - antes + 1];
